#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Actual native life reservations are replayed; no life is guessed/deducted by UI.
public static class PhyrexianPaymentPresentationValidation
{
    const string RootPath=".tools/mana-variants-1006/phyrexian-ui";
    public static string Output {get;private set;}
    [Serializable] class Result {public string folder;public string spell;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool pass,string error){if(!pass)throw new Exception(error);}
    static Result Meta(string name)=>JsonUtility.FromJson<Result>(File.ReadAllText(".tools/mana-variants-1006/native/"+name+"-result.json"));
    static ForgeSeatView Read(string name,string label)=>JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(Path.Combine(Meta(name).folder,label+".json")));
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.3f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Click(Button b){File.AppendAllText(Output+"/interaction.txt",GamePreferences.Language+" click "+b.name+" interactable="+b.interactable+"\n");var r=(RectTransform)b.transform;foreach(float x in new[]{.5f,.2f,.8f})foreach(float y in new[]{.5f,.2f,.8f}){var p=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left,position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(new Vector2(Mathf.Lerp(r.rect.xMin,r.rect.xMax,x),Mathf.Lerp(r.rect.yMin,r.rect.yMax,y))))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<Button>()!=b)continue;Check(b.interactable,"Life payer disabled");ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}throw new Exception("Ray blocked "+b.name);}
    static Button Payer()=>Root.Find("PlayerPlate").GetComponent<Button>();
    static Button Cancel()=>Root.Find("CornerCluster/ControlRow/ManaPaymentActions/CancelPayment").GetComponent<Button>();
    public static void Run(){Check(Application.isPlaying,"Play required");Output=RootPath+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output);File.WriteAllText(RootPath+"/latest.txt",Output);File.WriteAllText(RootPath+"/result.txt","RUNNING");var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("PhyrexianValidation").AddComponent<ForgeBattlefieldController>();ui.StartCoroutine(Guard(ui));}
    static IEnumerator Guard(ForgeBattlefieldController ui){var e=Validate(ui);try{while(true){object next;try{if(!e.MoveNext())break;next=e.Current;}catch(Exception error){File.WriteAllText(Output+"/result.txt","FAIL "+error);File.Copy(Output+"/result.txt",RootPath+"/result.txt",true);throw;}yield return next;}File.WriteAllText(Output+"/result.txt","PASS: actual native Phyrexian and K'rrik life-payment snapshots; zh-CN/en-US/ja-JP, native payers 1/2; payer life-total ray submits exact player ID once; stale, viewer, inputPending, other-player and unavailable-life guards; reserved life unchanged in HUD until real native commit; second reservation, cancel/recast and native resolution/recovery; sprite costs without braces. Rules and live networking are separate.");File.Copy(Output+"/result.txt",RootPath+"/result.txt",true);}finally{(e as IDisposable)?.Dispose();}}
    static IEnumerator Validate(ForgeBattlefieldController ui){string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool inputEnabled=module!=null&&module.enabled;if(module!=null)module.enabled=false;var banners=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=banners.Select(b=>b.enabled).ToArray();foreach(var b in banners)b.enabled=false;try{
        foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+15;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready&&(!change||revision!=GamePreferences.Revision),"Locale not ready");yield return Frame();
            foreach(string name in new[]{"phyrexian-life","phyrexian-mixed","phyrexian-cancel","phyrexian-black"}){var v=Read(name,"life-payment-0");int actor=v.request.seat,calls=0,last=-1;int nativeLife=v.players.First(p=>p.seat==actor).life;string id="player:"+v.players.First(p=>p.seat==actor).targetId;ui.Present(null,actor,false,null,null,"");var before=Read(name,"before-cast");int castCalls=0;ui.Present(before,actor,true,i=>castCalls++,null,"");yield return Frame();var spell=before.players.First(p=>p.seat==actor).hand.Single(c=>c.name==Meta(name).spell);Click(GameObject.Find("Card_"+spell.id).GetComponent<Button>());Check(castCalls==1,name+" actual hand cast ray");ui.Present(v,actor,true,i=>{calls++;last=i;},null,"");yield return Frame();Check(GameObject.Find("TargetOrigin")!=null,name+" casting preview missing");
                Check(calls==0,name+" early callback");Check(Payer().interactable&&!Root.Find("OpponentPlate").GetComponent<Button>().interactable,name+" wrong payer");Check(Root.Find("PlayerPlate/Life").GetComponent<Text>().text==nativeLife.ToString(),name+" life HUD wrong");
                var prompt=Root.Find("ManaPaymentPrompt").GetComponent<TMPro.TextMeshProUGUI>();prompt.ForceMeshUpdate();Check(!prompt.text.Contains("{")&&prompt.textInfo.characterInfo.Take(prompt.textInfo.characterCount).Any(c=>c.elementType==TMPro.TMP_TextElementType.Sprite&&c.isVisible),name+" missing cost glyph");
                ui.Choose(ui.OptionIndex(id),v.request.requestId-1);Check(calls==0,"Old life request submitted");Click(Payer());Payer().onClick.Invoke();Check(calls==1&&last==ui.OptionIndex(id),name+" player ID / duplicate");
                if(name!="phyrexian-mixed"){var second=Read(name,"life-payment-1");ui.Present(second,actor,true,i=>{calls++;last=i;},null,"");yield return Frame();Check(Payer().interactable&&Root.Find("PlayerPlate/Life").GetComponent<Text>().text==nativeLife.ToString(),name+" reserved life prematurely deducted");var selected=Root.Find("ManaPaymentPrompt").GetComponent<TMPro.TextMeshProUGUI>();Check(second.request.reservedLifePayment==2&&selected.text.Contains(lang=="zh-CN"?"已选生命":lang=="en-US"?"Life selected":"ライフ選択")&&!selected.text.Contains("phyrexian mana"),name+" reservation language/field");selected.ForceMeshUpdate();Check(!selected.enableAutoSizing&&selected.preferredWidth<=selected.rectTransform.rect.width&&selected.preferredHeight<=selected.rectTransform.rect.height,name+" reservation text overflow");if(lang=="zh-CN"){ScreenCapture.CaptureScreenshot(Output+"/"+name+"-reserved-life.png");yield return Frame();}Click(Payer());Check(calls==2&&last==ui.OptionIndex(id),name+" second reservation");}
                ui.Present(v,actor,false,i=>calls++,null,"");yield return Frame();int prior=calls;Payer().onClick.Invoke();Check(calls==prior&&!Payer().interactable,"Viewer spent life");
                ui.Present(v,actor,true,i=>calls++,null,"");var pending=JsonUtility.FromJson<ForgeSeatView>(JsonUtility.ToJson(v));pending.inputPending=true;ui.Present(pending,actor,false,i=>calls++,null,"");Check(!Payer().interactable,"Pending life accepts click");
                if(name=="phyrexian-cancel"){var cancel=Read(name,"cancel-payment");ui.Present(cancel,actor,true,i=>{calls++;last=i;},null,"");yield return Frame();Click(Cancel());Check(last==ui.OptionIndex("cancel"),"Life cancellation mapping");ui.Present(Read(name,"before-cast"),actor,true,i=>calls++,null,"");yield return Frame();Check(Root.Find("PlayerPlate/Life").GetComponent<Text>().text==nativeLife.ToString()&&!Cancel().gameObject.activeInHierarchy,"Cancel retained life/dock");}
                ui.Present(Read(name,"payment"),actor,true,i=>calls++,null,"");yield return Frame();Check(!Payer().interactable&&ui.OptionIndex(id)<0,"Life remains after native shards spent");
                ui.Present(Read(name,"resolved"),actor,true,i=>calls++,null,"");yield return Frame();Check(Root.Find("PlayerPlate/Life").GetComponent<Text>().text=="1"&&!Cancel().gameObject.activeInHierarchy,"Committed life / release mismatch");
                if(lang=="zh-CN"){ui.Present(v,actor,true,i=>calls++,null,"");yield return Frame();ScreenCapture.CaptureScreenshot(Output+"/"+name+".png");yield return Frame();}
            }
            foreach(string name in new[]{"phyrexian-insufficient","phyrexian-prohibited","phyrexian-prohibited-mana"}){string label=name.EndsWith("-mana")?"payment":"insufficient";var v=Read(name,label);int actor=v.request.seat,calls=0;ui.Present(null,actor,false,null,null,"");ui.Present(v,actor,true,i=>calls++,null,"");yield return Frame();string id="player:"+v.players.First(p=>p.seat==actor).targetId;Check(ui.OptionIndex(id)<0&&!Payer().interactable,"Forbidden/unavailable life option invented");Payer().onClick.Invoke();Check(calls==0,"Forbidden life submission");if(label=="insufficient"){var spell=v.players.First(p=>p.seat==actor).hand.Single(c=>c.name==Meta(name).spell);Check(ui.OptionIndex("card:"+spell.id)<0,"Unavailable spell enabled");GameObject.Find("Card_"+spell.id).GetComponent<Button>().onClick.Invoke();Check(calls==0,"Unavailable spell submitted");}}
            var tax=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(".tools/mana-variants-1006/x-regression-final/counter-tax-resolution-tax.json"));int taxCalls=0,lastTax=-1;ui.Present(null,tax.request.seat,false,null,null,"");ui.Present(tax,tax.request.seat,true,i=>{taxCalls++;lastTax=i;},null,"");yield return Frame();var cost=Root.Find("ManaPaymentPrompt").GetComponent<TMPro.TextMeshProUGUI>();Check(tax.request.remainingManaCost=="{3}"&&tax.request.reservedLifePayment==0&&cost.text.Contains(CardSymbolText.Format("{3}"))&&!cost.text.Contains("Life selected")&&!cost.text.Contains("已选生命")&&!cost.text.Contains("ライフ選択"),"Resolution tax confused with reserved life");Click(Cancel());Check(taxCalls==1&&lastTax==ui.OptionIndex("cancel"),"Ordinary resolution payment callback");
        }
    }finally{ui.enabled=enabled;if(module!=null)module.enabled=inputEnabled;GamePreferences.SetLanguage(locale);for(int i=0;i<banners.Length;i++)if(banners[i]!=null)banners[i].enabled=flags[i];}}
}
#endif
